struct Student {
    string name;          // data member
    int marks;            // data member (out of 200)

    void set(string n, int m) {   // member function with parameters
        name = n;         // name means this object's name
        marks = m;
    }

    double percentage() { // member function that returns a value
        return marks * 100.0 / 200;
    }

    void print() {        // member function with no parameters
        cout << name << " " << marks << endl;
    }
};                        // semicolon after the closing brace

Student s1;                // create an object
s1.set("Ali", 80);         // object.function(arguments)
s1.print();

