#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int marks;

    void set(string n, int m) {
        name = n;
        marks = m;
    }

    void print() {
        cout << name << " scored " << marks << endl;
    }
};

int main() {
    Student s1;
    s1.set("Ali", 80);
    s1.print();
    Student s2;
    s2.set("Sara", 92);
    s2.print();
    return 0;
}

#include <iostream>
using namespace std;

struct Rectangle {
    double width;
    double height;

    double area() {
        return width * height;
    }

    double perimeter() {
        return 2 * (width + height);
    }
};

int main() {
    Rectangle r;
    cin >> r.width >> r.height;
    cout << "Area = " << r.area() << endl;
    cout << "Perimeter = " << r.perimeter() << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct BankAccount {
    string owner;
    double balance;

    void deposit(double amount) {
        if (amount > 0) balance += amount;
    }

    bool withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    void show() {
        cout << owner << ": Rs. " << balance << endl;
    }
};

int main() {
    BankAccount acc = {"Zainab", 5000};
    acc.deposit(1500);
    if (!acc.withdraw(10000))
        cout << "Insufficient balance" << endl;
    acc.withdraw(2000);
    acc.show();
    return 0;
}

